// Some portions generated by Claude
import louvain from 'graphology-communities-louvain';
import {layoutTopology, layoutNodeFixed} from './graph-layout-topology.ts';
import {computeNetworkLayout} from './graph-layout-network.ts';
import {graphNodeSize} from './graph-geometry.ts';
import {separateLayoutRectangles} from './graph-layout-overlap.ts';
import {computeSparseLayout} from './graph-layout-sparse.ts';
import {computeMultilevelLayout} from './graph-layout-multilevel.ts';
import {computeGroupCenters, orientLayoutGroups} from './graph-layout-group-centers.ts';
import {layoutCandidateScore} from './graph-layout-score.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type {Graph, PointerPosition} from './graph-types.ts';
import type {LayoutOptions, LayoutResult} from './graph-layout-engine.ts';

/** Named groups have priority. Automatic groups need actual internal cohesion;
 * a shared RDF hub or a long chain alone is not evidence for a compound group.
 * Removing broad hubs BEFORE partitioning avoids disconnected compound shells.
 */
export function layoutNeighborhoods(graph: Graph, options: LayoutOptions = {}) {
  const topology = layoutTopology(graph), n = graph.nodes.length;
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  const parent = Int32Array.from({length: n}, (_, i) => i), manual = new Uint8Array(n);
  const root = (i: number): number => {while (parent[i] !== i) {parent[i] = parent[parent[i]]; i = parent[i];} return i;};
  for (const group of options.groups ?? []) {
    let first = -1;
    for (const id of group.nodeIds) {
      const i = index.get(id); if (i === undefined) continue;
      manual[i] = 1;
      if (first < 0) first = i;
      else parent[root(i)] = root(first);
    }
  }
  const groups: number[][] = [], named = new Map<number, number[]>();
  graph.nodes.forEach((_, i) => {if (manual[i]) {const r = root(i); if (!named.has(r)) named.set(r, []); named.get(r)!.push(i);}});
  groups.push(...named.values());
  const assigned = new Uint8Array(manual);
  const candidate = topology.copy();
  const hubLimit = Math.max(12, Math.sqrt(n) * 1.5);
  topology.forEachNode(id => {
    if (manual[Number(id)] || topology.degree(id) >= hubLimit) candidate.dropNode(id);
  });
  const components: string[][] = [], connected = new Set<string>();
  candidate.forEachNode(seed => {
    if (connected.has(seed)) return;
    const queue = [seed]; connected.add(seed);
    for (let i = 0; i < queue.length; i++) candidate.forEachNeighbor(queue[i], next => {
      if (!connected.has(next)) {connected.add(next); queue.push(next);}
    });
    components.push(queue);
  });
  if (components.length > 1) {
    // A branch attached only through a removed shared hub is already a real
    // neighborhood. Do not split it again to optimize a global modularity score.
    components.forEach(component => {
      if (component.length < 4) return;
      const members = component.map(Number); members.forEach(i => {assigned[i] = 1;}); groups.push(members);
    });
  }
  // Trees and cycles do not become arbitrary chunks just to satisfy modularity.
  if (components.length === 1 && candidate.order >= 8 && candidate.size >= candidate.order &&
      candidate.someNode(id => candidate.degree(id) > 2)) {
    const partition = louvain(candidate, {randomWalk: false, resolution: 1});
    const visited = new Set<string>();
    candidate.forEachNode(seed => {
      if (visited.has(seed)) return;
      const queue = [seed]; visited.add(seed);
      let inner = 0, boundary = 0;
      for (let cursor = 0; cursor < queue.length; cursor++) {
        const id = queue[cursor];
        candidate.forEachNeighbor(id, next => {
          if (partition[next] !== partition[seed]) {boundary++; return;}
          inner++;
          if (!visited.has(next)) {visited.add(next); queue.push(next);}
        });
      }
      // Every accepted group is connected and predominantly internally
      // connected. Weak evidence stays ungrouped; the quality gate can still
      // reject these proposals in favor of an ordinary network layout.
      if (queue.length >= 4 && queue.length < n && inner >= queue.length * 1.8 && inner / Math.max(1, inner + boundary) >= .7) {
        const members = queue.map(Number); members.forEach(i => {assigned[i] = 1;}); groups.push(members);
      }
    });
  }
  graph.nodes.forEach((_, i) => {if (!assigned[i]) groups.push([i]);});
  return {groups, topology};
}

/** Lay out group interiors, then their measured bounding rectangles, then
 * translate each interior rigidly. Later node-level nudges cannot mix groups.
 * Pins lock their group's translation, while free groups can make room for it.
 */
export function computeGroupedLayout(graph: Graph, options: LayoutOptions = {}): LayoutResult | undefined {
  if (options.nodeSizes || graph.nodes.length < 4) return undefined;
  const {groups, topology} = layoutNeighborhoods(graph, options);
  if (groups.length < 2 || groups.every(group => group.length === 1)) return undefined;
  const owner = new Uint32Array(graph.nodes.length), parts: Graph[] = groups.map(members => ({
    nodes: members.map(i => graph.nodes[i]), edges: [], revision: graph.revision,
  }));
  groups.forEach((members, c) => members.forEach(i => {owner[i] = c;}));
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  for (const edge of graph.edges) {
    const a = index.get(edge.source), b = index.get(edge.target);
    if (a !== undefined && b !== undefined && owner[a] === owner[b]) parts[owner[a]].edges.push(edge);
  }
  const local = new Map<string, PointerPosition>(), sizes = new Map<string, {width: number; height: number}>();
  const coarse: Graph = {nodes: [], edges: [], revision: graph.revision};
  parts.forEach((part, c) => {
    const inner = (options.repairOnly || (part.nodes.length > 1500 && part.nodes.some(node => layoutNodeFixed(node, options)))
      ? computeSparseLayout(part, {...options, repairOnly: true})
      : part.nodes.length > 1500 ? computeMultilevelLayout(part, options) : computeNetworkLayout(part, options)).positions;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    part.nodes.forEach(node => {
      const p = inner.get(node.id)!, size = graphNodeSize(node);
      minX = Math.min(minX, p.x - size.width / 2); maxX = Math.max(maxX, p.x + size.width / 2);
      minY = Math.min(minY, p.y - size.height / 2); maxY = Math.max(maxY, p.y + size.height / 2);
    });
    const x = (minX + maxX) / 2, y = (minY + maxY) / 2, id = String(c);
    sizes.set(id, {width: maxX - minX + gap.groupGap, height: maxY - minY + gap.groupGap});
    coarse.nodes.push({id, label: '', kind: 'iri', x, y, pinned: part.nodes.some(node => layoutNodeFixed(node, options))});
    part.nodes.forEach(node => {const p = inner.get(node.id)!; local.set(node.id, {x: p.x - x, y: p.y - y});});
  });
  const pairs = new Set<string>();
  topology.forEachEdge((_edge, _attr, a, b) => {
    const x = owner[Number(a)], y = owner[Number(b)];
    if (x === y) return;
    const key = x < y ? `${x}:${y}` : `${y}:${x}`;
    if (!pairs.has(key)) {pairs.add(key); coarse.edges.push({id: key, source: String(x), target: String(y), label: '', predicate: 'urn:layout:link'});}
  });
  const coarseOptions = {nodeSizes: sizes, seed: options.seed, refine: options.refine || options.incremental || Boolean(options.localNodeIds?.size)};
  const centers = (options.repairOnly || (coarse.nodes.length > 1500 && coarse.nodes.some(node => node.pinned))
    ? computeSparseLayout(coarse, {...coarseOptions, repairOnly: true})
    : coarse.nodes.length > 1500 ? computeMultilevelLayout(coarse, coarseOptions) : {positions: computeGroupCenters(coarse, coarseOptions)}).positions;
  const search = graph.nodes.length <= 350 && graph.edges.length <= 600 &&
    !options.refine && !options.incremental && !options.repairOnly && !options.localNodeIds?.size;
  const anchor = coarse.nodes.find(n => n.pinned);
  const origin = anchor ? centers.get(anchor.id)! : {x: [...centers.values()].reduce((sum, p) => sum + p.x, 0) / centers.size,
    y: [...centers.values()].reduce((sum, p) => sum + p.y, 0) / centers.size};
  let best: Map<string, PointerPosition> | undefined, bestScore = Infinity;
  const aspect = [...sizes.values()].reduce((sum, size) => sum + size.width + gap.nodeGapX, 0) /
    [...sizes.values()].reduce((sum, size) => sum + size.height + gap.nodeGapY, 0);
  // Compaction is a candidate, never a final unverified nudge. It may stack
  // wide group boxes along their short axis, avoiding long horizontal strips.
  for (const rotate of search ? [false, true] : [false]) for (const factor of search ? [1, .75, .5] : [1]) {
    const proposed = new Map(coarse.nodes.map(node => {
      const p = centers.get(node.id)!;
      const dx = p.x - origin.x, dy = p.y - origin.y;
      // Rotate the center graph in rectangle-normalized coordinates, not its
      // cards or group interiors. Wide groups can stack instead of forming a
      // viewport-spanning strip. The measured boxes are verified afterwards.
      return [node.id, node.pinned ? {...p} : {x: origin.x + (rotate ? -dy * aspect : dx) * factor,
        y: origin.y + (rotate ? dx / aspect : dy) * factor}];
    }));
    separateLayoutRectangles(coarse, proposed, {nodeSizes: sizes, repairOnly: true});
    const positions = new Map<string, PointerPosition>();
    parts.forEach((part, c) => {
      const center = proposed.get(String(c))!;
      part.nodes.forEach(node => {
        const p = local.get(node.id)!;
        positions.set(node.id, layoutNodeFixed(node, options) ? {x: node.x ?? 0, y: node.y ?? 0} : {x: p.x + center.x, y: p.y + center.y});
      });
    });
    orientLayoutGroups(graph, groups, positions, proposed, options);
    // Anchored group boxes may already intersect: pins take priority, but
    // movable node cards must still be placed in free space.
    separateLayoutRectangles(graph, positions, {...options, repairOnly: true});
    if (!search) return {positions, bends: new Map(), grouped: true};
    const score = layoutCandidateScore(graph, positions, options);
    if (score < bestScore) {bestScore = score; best = positions;}
  }
  return {positions: best!, bends: new Map(), grouped: true};
}
